tus": "draft", "id": "01f8c39e-a2e9-5539-9e26-8926e64fc703"}, {"name": "唐赛儿", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "唐赛儿在蒲台起事。", "biography": null, "status": "draft", "id": "36d5a0ec-fcd3-587c-a4ab-b8fcf1b3c5d4"}, {"name": "柳升", "aliases": ["安远侯"], "era": "明", "birth_year": null, "death_year": null, "description": "柳升以安远侯身份率领大营。", "biography": null, "status": "draft", "id": "14f79103-5514-5b8a-b46f-74887204ab53"}, {"name": "朱荣", "aliases": ["朱仲华"], "era": "明", "birth_year": null, "death_year": null, "description": "朱荣领兵担任前锋。", "biography": null, "status": "draft", "id": "7c50ae9b-791a-520b-9a9b-f076a35ad63f"}, {"name": "朱高炽", "aliases": ["明仁宗"], "era": "明", "birth_year": null, "death_year": null, "description": "明仁宗，永樂22年（1424年）八月，朱高炽即皇帝位。", "biography": null, "status": "draft", "id": "2dded14d-7183-56b5-9029-ca93826c1e80"}, {"name": "朱瞻基", "aliases": ["明宣宗"], "era": "明", "birth_year": null, "death_year": null, "description": "明宣宗，洪熙元年（1425年）六月，朱瞻基即皇帝位。", "biography": null, "status": "draft", "id": "888fc961-674c-52bf-b645-1351d5637434"}]'::jsonb)
