INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "黎利在交阯起兵，朱广击败其部", "description": "永乐十六年正月甲寅，黎利在交阯起兵反抗明廷。明廷的都督朱广率部击败黎利所部。", "start_year": 1418, "end_year": 1418, "time_original": "永乐十六年正月甲寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f4bfeec1-8cd0-5332-8d40-0d62aa06ea17"}, {"title": "倭寇攻陷松门卫，石鲁获罪被处死", "description": "永乐十六年正月甲戌，倭寇攻陷松门卫，按察司佥事石鲁因此获罪被处死。", "start_year": 1418, "end_year": 1418, "time_original": "永乐十六年正月甲戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "87846ec5-8a53-5360-a1f1-b0bc9df0da2c"}, {"title": "徐亨和夏贵奉命驻防开平", "description": "永乐十六年正月，明廷派兴安伯徐亨和都督夏贵在开平布防。", "start_year": 1418, "end_year": 1418, "time_original": "永乐十六年正月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "34729a29-52d6-56e9-a0de-eec007c45077"}, {"title": "四忙县有人起事杀死知县，李彬遣兵击退", "description": "永乐十六年二月辛丑，交阯四忙县有人反抗明廷并杀死知县欧阳智。李彬派将领率兵将他们击退。", "start_year": 1418, "end_year": 1418, "time_original": "永乐十六年二月辛丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1143d54f-e18b-5492-896a-bfbf1edd4ec3"}, {"title": "明廷授李骐等人不同等第的进士资格", "description": "永乐十六年三月甲寅，朝廷向李骐等人授予不同等第的进士资格。", "start_year": 1418, "end_year": 1418, "time_original": "永乐十六年三月甲寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "533f71a8-a396-58e9-8333-831a52569e5d"}, {"title": "刘鉴奉命赴大同戍边", "description": "永乐十六年三月，明廷派都督佥事刘鉴到大同防备边境。", "start_year": 1418, "end_year": 1418, "time_original": "永乐十六年三月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "adc0dcc3-da78-56ed-9fe7-3343c1cb1ae9"}, {"title": "重修的《太祖实录》完成", "description": "永乐十六年五月庚戌，朝廷重修的《太祖实录》完成。", "start_year": 1418, "end_year": 1418, "time_original": "永乐十六年五月庚戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6bcbd115-b64b-5e64-a1db-f270c121c064"}, {"title": "胡广去世", "description": "永樂16年（1418年）五月，胡广去世。", "start_year": 1418, "end_year": 1418, "time_original": "永樂16年（1418年）五月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "c5e6a933-6f27-57b4-bcfb-714ef96f2077"}, {"title": "明成祖责陕西官署瞒报灾情，命开仓赈济", "description": "永乐十六年七月己巳，明成祖得知陕西连年歉收，百姓流离、饿死。朱棣斥责当地官署迟迟不救济、也不报告，并命他们尽快开仓放粮。", "start_year": 1418, "end_year": 1418, "time_original": "永乐十六年七月己巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "594487ab-ba2f-5353-be82-e36a03fd6cf9"}, {"title": "梁潜、周冕因辅导太子被追责，下狱身亡", "description": "永乐十六年七月，赞善梁潜、司谏周冕被认定辅导皇太子有过失，两人下狱后都死去。", "start_year": 1418, "end_year": 1418, "time_original": "永乐十六年七月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "aec86c12-d9b0-54cc-a15b-dfaa94d4f6c2"}, {"title": "明成祖谕令司法官署依法惩治贪赃", "description": "永乐十六年十二月戊子，明成祖谕告主管司法的官署，贪赃的官吏侵害百姓，应依法惩处。", "start_year": 1419, "end_year": 1419, "time_original": "永乐十六年十二月戊子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "74ad29e8-efc3-5c7d-998f-eb7e6759eeb3"}, {"title": "王通奉命赶赴陕西赈济饥民", "description": "永乐十六年十二月辛丑，成山侯王通奉命乘驿马赴陕西救济饥民。", "start_year": 1419, "end_year": 1419, "time_original": "永乐十六年十二月辛丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6395ff53-653b-5d1e-9d64-ecc53a027459"}, {"title": "本纪汇记永乐十六年多地入贡", "description": "永乐十六年，暹罗、占城、爪哇等多地入贡，琉球中山两次入贡。来使各自的日期未在这段年末汇记中开列。 按原历纪年，事情发生在公元1418至1419年之间。", "start_year": null, "end_year": null, "time_original": "永乐十六年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6b4800a0-392a-5925-84f6-cd78cd0602df"}, {"title": "徐亨奉命加强兴和、开平、大同防务", "description": "永乐十七年二月乙酉，明廷派兴安伯徐亨整备兴和、开平和大同的防务。", "start_year": 1419, "end_year": 1419, "time_original": "永乐十七年二月乙酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6bc7d853-9c80-5ca7-bdbb-579e83db284f"}, {"title": "方政在可蓝栅击败黎利所部", "description": "永乐十七年五月丙午，都督方政在可蓝栅击败黎利率领的部队。", "start_year": 1419, "end_year": 1419, "time_original": "永乐十七年五月丙午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6e4fa7d7-13d8-5eda-a4cc-8421e7034ac7"}, {"title": "明廷免去顺天府上年水灾所涉田租", "description": "永乐十七年六月壬午，朝廷减免顺天府上年遇水灾地区的田租。", "start_year": 1419, "end_year": 1419, "time_original": "永乐十七年六月壬午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "25e44709-651a-5339-9458-642d18c2d63b"}, {"title": "刘江在望海埚击败倭寇", "description": "永乐十七年六月戊子，刘江率部在望海埚击败倭寇。本纪紧接记载，刘江受封广宁伯。", "start_year": 1419, "end_year": 1419, "time_original": "永乐十七年六月戊子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "827f1c6e-bd78-5eae-b588-dcfec87d668a"}, {"title": "郑和归来", "description": "永乐十七年七月庚申，《明史》本纪记郑和归来。", "start_year": 1419, "end_year": 1419, "time_original": "永乐十七年七月庚申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "58fd53ff-669a-5193-b80f-8063964827e5"}, {"title": "本纪记马骐激起乂安土知府潘僚反抗", "description": "永乐十七年八月，据《明史》本纪，宦官马骐的行为激起交阯乂安土知府潘僚反抗明廷。", "start_year": 1419, "end_year": 1419, "time_original": "永乐十七年八月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f2b2c9a4-6643-5c66-b57c-8b99652038fa"}, {"title": "礼官请因庆云上表致贺，明成祖未准许", "description": "永乐十七年九月丙辰，本纪记出现庆云。礼官请求上表致贺，明成祖未予准许。", "start_year": 1419, "end_year": 1419, "time_original": "永乐十七年九月丙辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "729721d3-bd6f-5b4d-a687-4bb4f116c99a"}, {"title": "明廷要求外地死刑案送京复审并三次复奏", "description": "永乐十七年十二月庚辰，明成祖告谕主管司法的官署，地方官署所判死刑案件一律送京复审，经三次复奏才执行。", "start_year": 1420, "end_year": 1420, "time_original": "永乐十七年十二月庚辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "708973d0-5ff8-5b6f-a893-3d5cccb79e7a"}, {"title": "刘仲廉奉命核实交阯户口和田赋", "description": "永乐十七年十二月乙未，工部侍郎刘仲廉受命核实交阯的户口和田赋，调查当地军民的处境。", "start_year": 1420, "end_year": 1420, "time_original": "永乐十七年十二月乙未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "54faef4f-919d-54c6-a44e-10830e888af2"}, {"title": "本纪汇记永乐十七年多地入贡", "description": "永乐十七年，哈密、土鲁番、真腊等地入贡，琉球中山四次入贡。本纪在年末合记各次来使。 按原历纪年，事情发生在公元1419至1420年之间。", "start_year": null, "end_year": null, "time_original": "永乐十七年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "cbd21d7a-94b2-5b87-8ef2-b3fb6915eb0f"}, {"title": "李彬等在磊江击败黎利部队", "description": "永乐十八年正月癸卯，李彬与都指挥孙霖、徐謜在磊江击败黎利所部。", "start_year": 1420, "end_year": 1420, "time_original": "永乐十八年正月癸卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6fbe1e6c-db0d-5dcc-a931-2e3a56f7b2a2"}, {"title": "杨荣升任文渊阁大学士，兼翰林院学士", "description": "永樂18年（1420年）闰正月，杨荣升任文渊阁大学士，兼翰林院学士。", "start_year": 1420, "end_year": 1420, "time_original": "永樂18年（1420年）闰正月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "43cdd73c-67c8-5fa3-988d-a9779d578991"}, {"title": "金幼孜升任文渊阁大学士，兼翰林院学士", "description": "永樂18年（1420年）闰正月，金幼孜升任文渊阁大学士，兼翰林院学士。", "start_year": 1420, "end_year": 1420, "time_original": "永樂18年（1420年）闰正月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "df782d4a-96c3-564c-bf62-6d3e8316e719"}, {"title": "明廷选拔马麟等十三人出任地方官", "description": "永乐十八年闰正月庚辰，明廷从未任官的人士中选拔马麟等十三人，出任布政使、参政或参议。", "start_year": 1420, "end_year": 1420, "time_original": "永乐十八年闰正月庚辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c3f8e5ba-d7c8-5c5a-92a4-c33617cdf49e"}, {"title": "唐赛儿在蒲台起事，柳升奉命出兵", "description": "永乐十八年二月己酉，唐赛儿在蒲台起事，明廷命安远侯柳升率军征讨。", "start_year": 1420, "end_year": 1420, "time_original": "永乐十八年二月己酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3b624403-7ffb-5ed0-a07f-1cf069cbdb5e"}, {"title": "明军在卸石栅寨击败起事部队，唐赛儿离开", "description": "永乐十八年三月辛巳，明军在卸石栅寨击败唐赛儿的部队。明军都指挥刘忠在交战中死去，唐赛儿逃走。", "start_year": 1420, "end_year": 1420, "time_original": "永乐十八年三月辛巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ee968125-dbb0-566e-b205-dffb488fc827"}, {"title": "卫青和王真分别在安丘、诸城击败起事部队", "description": "永乐十八年三月甲申，山东都指挥佥事卫青在安丘、指挥王真在诸城分别击败起事部队，随后有俘虏被送往京师。", "start_year": 1420, "end_year": 1420, "time_original": "永乐十八年三月甲申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "281d592e-fefa-52d4-bb7e-f85722305e98"}, {"title": "山东布政使储埏等被追究放纵盗匪责任并处死", "description": "永乐十八年三月戊子，山东布政使储埏、张海和按察使刘本等人被按放纵盗匪治罪处死。", "start_year": 1420, "end_year": 1420, "time_original": "永乐十八年三月戊子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "87c97af0-5be2-5a52-9820-a625ad4ba67b"}, {"title": "柳升因军队滞留被追究，旋即获释", "description": "永乐十八年三月戊戌，明廷以柳升在平乱中逗留为由，召他交有关官署问罪。柳升随后获释。", "start_year": 1420, "end_year": 1420, "time_original": "永乐十八年三月戊戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c4629a29-20f8-58e3-a17c-4c9e1f089cb5"}, {"title": "朱荣奉命镇守辽东", "description": "永乐十八年五月壬午，朝廷派左都督朱荣镇守辽东。", "start_year": 1420, "end_year": 1420, "time_original": "永乐十八年五月壬午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "92836355-f4fb-5b51-8447-f4a95cec4dc8"}, {"title": "交阯参政侯保、冯贵在交战中阵亡", "description": "永乐十八年五月庚寅，交阯参政侯保、冯贵抵御与明军交战的部队，二人在交战中阵亡。", "start_year": 1420, "end_year": 1420, "time_original": "永乐十八年五月庚寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "46fa9f70-3a11-5428-8b32-b7c53442d4e0"}, {"title": "北京发生地震", "description": "永乐十八年六月丙午，北京发生地震。", "start_year": 1420, "end_year": 1420, "time_original": "永乐十八年六月丙午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e1922df6-fd12-5f62-92bf-7f644deee7c4"}, {"title": "徐亨奉命驻防开平", "description": "永乐十八年七月丁亥，朝廷派徐亨在开平布防。", "start_year": 1420, "end_year": 1420, "time_original": "永乐十八年七月丁亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "bcbd533c-0ae9-5c9c-a078-b5b1b8adfb7e"}, {"title": "八月初一发生日食", "description": "永乐十八年八月初一，发生日食。", "start_year": 1420, "end_year": 1420, "time_original": "永乐十八年八月丁酉朔", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "818dd97f-d056-5c5c-9a85-57cc2a4da40b"}, {"title": "明成祖召皇太子朱高炽前来", "description": "永乐十八年九月己巳，明成祖召皇太子朱高炽前来。", "start_year": 1420, "end_year": 1420, "time_original": "永乐十八年九月己巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9efbc188-1285-525e-9e78-6c8b1d8818ee"}, {"title": "明成祖下诏来年改定南京与北京的称谓", "description": "永乐十八年九月丁亥，明成祖朱棣下诏，自次年起原京师改称南京，北京改称京师。", "start_year": 1420, "end_year": 1420, "time_original": "永乐十八年九月丁亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b5a7febf-26a0-504a-a92c-b671bc6ddda6"}, {"title": "李彬派方政在老挝击败黎利部队", "description": "永乐十八年十月庚申，李彬派指挥使方政出战，方政在老挝击败黎利所部。", "start_year": 1420, "end_year": 1420, "time_original": "永乐十八年十月庚申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6654611b-3162-5025-8389-d15de5be19b5"}, {"title": "明廷颁诏公布迁都北京", "description": "永乐十八年十一月戊辰，朝廷向天下颁诏，公布迁都北京的决定。", "start_year": 1420, "end_year": 1420, "time_original": "永乐十八年十一月戊辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "097812c3-3b90-5674-9f71-63367728ef9b"}, {"title": "明廷赈济青州、莱州的饥民", "description": "永乐十八年十一月，明廷在青州、莱州救济饥民。 按原历纪年，事情发生在公元1420至1421年之间。", "start_year": null, "end_year": null, "time_original": "永乐十八年十一月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "adfa8e63-d96c-5b4e-851a-041ec627e250"}, {"title": "皇太子与皇太孙到达北京", "description": "永乐十八年十二月己未，皇太子朱高炽和皇太孙朱瞻基到达北京。", "start_year": 1421, "end_year": 1421, "time_original": "永乐十八年十二月己未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "33febfab-a169-5782-a29d-806d0fd91a7e"}, {"title": "北京祭祀建筑和宫殿建成", "description": "永乐十八年十二月癸亥，本纪记北京用于祭祀的郊坛、庙宇以及宫殿建成。", "start_year": 1421, "end_year": 1421, "time_original": "永乐十八年十二月癸亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "bd6a1824-7350-54e5-ac91-e6d0fa7e696d"}, {"title": "明廷设东厂，命宦官负责查察事务", "description": "永乐十八年，《明史》本纪记明廷设置东厂，派宦官负责查察事务。 按原历纪年，事情发生在公元1420至1421年之间。", "start_year": null, "end_year": null, "time_original": "永乐十八年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "842d51fd-1ef2-5574-b66a-100e440811fc"}, {"title": "古麻剌朗王来朝，本纪另记多地入贡", "description": "永乐十八年，古麻剌朗王来到明廷，暹罗、占城、爪哇、满剌加、苏门答剌和苏禄西王另有入贡记录。 按原历纪年，事情发生在公元1420至1421年之间。", "start_year": null, "end_year": null, "time_original": "永乐十八年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e0b6b01b-eb5c-5115-ba62-e97ee86cbc1d"}, {"title": "刘江受封广宁伯", "description": "望海埚一战后，明廷封刘江为广宁伯。卷七本纪将受封与战斗接续记载，受封的具体日期待考。", "start_year": null, "end_year": null, "time_original": "望海埚交战之后，封爵确日待考", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6e26eec5-35e2-5c95-a677-54e192b7c017"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

