INSERT INTO public.fact_claim (id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status)
SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "person", "field_path": "description", "claim_text": "黎利在交阯起兵。", "citation": "《明史》卷7·本纪第七·成祖三·mingshi-2f603db3d81e-p001183；永乐十六年正月甲寅", "note": "原文：十六年春正月甲寅，交阯黎利反，都督朱廣擊敗之；核对说明：卷三二一安南传同记黎利在永乐年间起兵，且与李彬、方政对阵，身份与卷七纪事相合。", "status": "draft", "id": "907ccbfd-705e-57a2-9edc-cf32e2424170", "subject_id": "c3cb3b52-845e-5798-86eb-c3dfdd072dcd", "source_id": "efadbae2-936c-5523-98b6-11e50e8b2cfa"}, {"subject_table": "event", "field_path": "description", "claim_text": "永乐十六年正月甲寅，黎利在交阯起兵反抗明廷。明廷的都督朱广率部击败黎利所部。", "citation": "《明史》卷7·本纪第七·成祖三·mingshi-2f603db3d81e-p001183；永乐十六年正月甲寅", "note": "原文：十六年春正月甲寅，交阯黎利反，都督朱廣擊敗之；核对说明：该摘录逐字支持所列行动及其阶段；时间取本段及相邻年条。", "status": "draft", "id": "8ce45f45-fa49-5261-a986-4732e088e1c1", "subject_id": "f4bfeec1-8cd0-5332-8d40-0d62aa06ea17", "source_id": "efadbae2-936c-5523-98b6-11e50e8b2cfa"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "原历永乐十六年正月甲寅。DDBC历表换算所据为1418-02-17至1418-02-17，据此核对公元发生年份。", "citation": "《明史》卷7·本纪第七·成祖三·mingshi-2f603db3d81e-p001183；永乐十六年正月甲寅", "note": "原文：十六年春正月甲寅，交阯黎利反，都督朱廣擊敗之；核对说明：原历纪年按本段及相邻年条核对，史料未载的具体日保留为空。", "status": "draft", "id": "48115632-6a53-5e98-a566-5f3281e0eeef", "subject_id": "f4bfeec1-8cd0-5332-8d40-0d62aa06ea17", "source_id": "efadbae2-936c-5523-98b6-11e50e8b2cfa"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "在交阯起兵", "citation": "《明史》卷7·本纪第七·成祖三·mingshi-2f603db3d81e-p001183；永乐十六年正月甲寅", "note": "原文：十六年春正月甲寅，交阯黎利反，都督朱廣擊敗之；核对说明：只采用本段明确参与者和行动角色，既有连接按稳定编号复用。", "status": "draft", "id": "b9e7e020-3d5e-56d1-8c07-df41f3eafb37", "subject_id": "8d751dcc-9d7d-5417-b7ee-d6d413901688", "source_id": "efadbae2-936c-5523-98b6-11e50e8b2cfa"}, {"subject_table": "event", "field_path": "description", "claim_text": "永乐十六年正月甲戌，倭寇攻陷松门卫，按察司佥事石鲁因此获罪被处死。", "citation": "《明史》卷7·本纪第七·成祖三·mingshi-2f603db3d81e-p001183；永乐十六年正月甲戌"